let cache: Map<string, number> | null = null;

/** Word to valence, built once on first use. */
export function baseLexicon(): Map<string, number> {
  if (cache) return cache;
  const map = new Map<string, number>();
  for (const entry of PACKED.split("|")) {
    const cut = entry.indexOf("\u001f");
    if (cut === -1) continue;
    map.set(entry.slice(0, cut), Number(entry.slice(cut + 1)));
  }
  cache = map;
  return map;
}

